  WHEN '3ffff54e-8e51-b259-d42c-4455e2ac36ec' THEN '70f495cf-d3e7-ff9d-63c3-4761a3edff06'::uuid
  WHEN 'c1ba9901-04fd-41ef-9050-1c04a9729b41' THEN '2c64b27e-eef4-c4a2-9936-a539deac422f'::uuid
  WHEN 'cc3f1d84-4b2e-7db4-61f0-888a5a0bb679' THEN '49908498-2cee-10b3-b937-7e4f92968147'::uuid
  WHEN '5076c65c-fa94-d1d6-4e8e-f10d6bd96464' THEN '7e4f5c89-a006-c01b-e6cb-60b9d461dcb7'::uuid
